sys_script_include.script:
var CheckLocationAvailability = Class.create();
CheckLocationAvailability.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	checkLocationAvailability: function() {
        var location = this.getParameter('sysparm_location');
        var eventDate = this.getParameter('sysparm_event_date');

        var gr = new GlideRecord('x_1790227_event_ma_event');
        gr.addQuery('u_location', location);
        gr.addQuery('u_event_date', '>=', eventDate + ' 00:00:00');
        gr.addQuery('u_event_date', '<=', eventDate + ' 23:59:59');
        gr.query();

        if (gr.hasNext()) {
            return 'false'; 
        }
        return 'true'; 
    },
    type: 'CheckLocationAvailability'
});
